{
  "name_zh": "凝寒觸",
  "concept": "以低溫凍結空氣，將寒意注入目標體內使其行動遲滯。",
  "cast_flavor": "指尖劃過虛空，霜色光暈纏繞而去，觸及之處泛起白霧並減緩其步伐。"
}

{
  "name_zh": "霜息",
  "concept": "將冰霜的寒意纏繞於目標周身，使其動作因寒氣浸染而變得遲緩。",
  "cast_flavor": "低溫的氣息自指尖擴散，蒼白的光暈纏上對手，步履隨之沉重下來。"
}

{
  "name_zh": "溫潤迴響",
  "concept": "一道柔和的頻率擴散開來，撫平周圍創傷，帶來短暫的安寧。",
  "cast_flavor": "微光自掌心漾出，如暖流般包裹身週，讓疼痛緩緩退去。"
}

{
  "name_zh": "餘燼護體",
  "concept": "將體內殘存的熱能凝結為壁障，抵擋外來衝擊。",
  "cast_flavor": "皮膚下湧起微光，緊貼周身形成一層隱形的硬殼。"
}

{
  "name_zh": "腐蝕滴落",
  "concept": "凝結的毒液從虛空中滴下，擊中目標時滲入肌膚，引發持續的毒素侵蝕。",
  "cast_flavor": "指尖輕彈，一滴漆黑的毒液脫手而出，劃過空氣後精準地砸在敵人身軀上，迅速蔓延開來。"
}

{
  "name_zh": "凝滯毒霧",
  "concept": "在目標周圍佈下隱形的毒質結界，隨時間推移不斷累積層數，最終引發劇烈的爆発。",
  "cast_flavor": "指尖輕點，無色的霧氣纏繞敵人身軀，每一秒的沉默都在加深那即將到來的劇痛。"
}

{
  "name_zh": "雷痕標識",
  "concept": "以閃電為引，在目標身上刻下顯著的殘響印記。",
  "cast_flavor": "指尖輕點，一道細微的雷弧纏繞周身，將無形的標記烙入空氣。"
}

{
  "name_zh": "碎界牽引",
  "concept": "以法器震動源晶頻率，將單體目標强行拉近并留下殘頻層數。",
  "cast_flavor": "法器輕叩虛空，一道無形的力場纏住敵人身軀，伴隨清脆的碎裂聲將其拽至身前。"
}

{
  "name_zh": "裂空拽引",
  "concept": "法器震動虛空，將目標強行拉近並在其身上疊加殘頻層數。",
  "cast_flavor": "指尖彈出無形鎖鏈，纏住敵人身軀伴隨碎裂聲響，將其硬生生拽至身前。"
}

{
  "name_zh": "雷鳴清道",
  "concept": "以帶電的錐形力量貫穿前方，剝除附著在目標身上的增益效果並造成傷害。",
  "cast_flavor": "法杖尖端迸出藍白電弧，如利刃般向前延伸，將周遭的異能震散成碎屑。"
}

{
  "name_zh": "電殲",
  "concept": "將目標身上的暈眩狀態轉化為純粹的雷電傷害，讓僵滯的瞬間成為崩解的前奏。",
  "cast_flavor": "指尖輕觸空氣中的靜電，目標周身的遲滯感被強行撕開，化作一道蒼白的閃電貫穿其體。"
}

