{
  "name_zh": "環抱生息",
  "concept": "以氣為引，在周身展開範圍光環，持續回復資源並隨時間累積層數。",
  "cast_flavor": "雙手結印，一道無形的氣流自足底升起，將身週包覆成靜默的光環。"
}

{
  "name_zh": "厚土承托",
  "concept": "大地之力匯聚成環，既撫平創傷也將敵人推開。",
  "cast_flavor": "腳下的岩層微微震動，一道厚重的土色光環擴散，將周圍的侵蝕之力向外抵擋。"
}

{
  "name_zh": "層疊光環",
  "concept": "以法術凝聚的光暈纏繞自身，隨施放次數疊加防護層數。",
  "cast_flavor": "指尖輕點，一圈圈柔和的光環自周身湧現，彼此交織成密實的壁壘。"
}

{
  "name_zh": "暗影汲納",
  "concept": "透過法器汲取目标的增益狀態，轉化為自身可累積的暗影層數。",
  "cast_flavor": "法器的陰影如觸手般纏上敵人，將對方的光輝一絲絲剝離並吸入體內。"
}

{
  "name_zh": "暗影汲納",
  "concept": "透過法器汲取目標的增益狀態，轉化為自身可累積的暗影層數。",
  "cast_flavor": "法器的陰影如觸手般纏上敵人，將對方的光輝一絲絲剝離並吸入體內。"
}

{
  "name_zh": "沉墜壓制",
  "concept": "法術凝成錐形重壓，將目標擊倒並使其陷入虛弱狀態。",
  "cast_flavor": "掌心匯聚無形的重量，錐狀力場垂直落下，將對手重重壓倒在地。"
}

{
  "name_zh": "寒土陷陣",
  "concept": "大地在低溫中失去支撐，裂開方陣般的深坑，將敵人凍結並拖入地下。",
  "cast_flavor": "地脈驟冷，岩層如冰塊般崩解下沉，方形陷阱張口吞噬著高處的立足點。"
}

{
  "name_zh": "寒土陷陣",
  "concept": "大地在低溫中失去支撐，裂開方陣般的深坑，將敵人拖入地下並造成冰霜傷害。",
  "cast_flavor": "地脈驟冷，岩層如冰塊般崩解下沉，方形陷阱張口吞噬著高處的立足點。"
}

{
  "name_zh": "地脈伏雷",
  "concept": "將大地之力凝結於目標腳下，形成隱蔽的震動核心，待時機成熟時釋放積蓄的衝擊。",
  "cast_flavor": "指尖輕點地面，無聲的裂痕在腳底蔓延，大地的躁動被暫時封印，只等那一瞬的崩解。"
}

{
  "name_zh": "沉土伏爆",
  "concept": "將大地的力量壓縮於目標身下，形成一個靜默的震動核心，在預定的時刻猛然炸開。",
  "cast_flavor": "掌心貼地，腳下的泥土無聲地隆起又落下，隱約有沉重的脈搏在其中跳動，只待崩解的一刻。"
}

{
  "name_zh": "隱夜蝕痕",
  "concept": "自無形處凝出的暗影觸碰，在目標身上留下持續削弱力量的殘痕。",
  "cast_flavor": "指尖劃過寂靜的空氣，一道幽暗的紋路悄然纏上敵人的肩頭。"
}

{
  "name_zh": "岩鎖牽引",
  "concept": "大地之力從足下湧起，將目標拽向身前並使其重疊的岩石紋路纏住全身。",
  "cast_flavor": "腳下的浮土瞬間硬化成粗獷的石鏈，猛然收緊，將敵人拖至面前重重摔在碎石堆上。"
}

{
  "name_zh": "風迴護環",
  "concept": "以流動的氣流構築無形屏障，在風中滋養疲憊的身軀。",
  "cast_flavor": "呼喚殘留的氣流盤旋周身，形成一層柔韌的光暈，撫平創傷並抵禦外敵。"
}

{
  "name_zh": "斷點躍遷",
  "concept": "撕裂空間的短距移動，在虛無中留下暫時的軌跡殘影。",
  "cast_flavor": "身影倏忽消散，於兩步之外重新凝聚，空氣中泛起細微的震顫。"
}

{
  "name_zh": "澄澈圓光",
  "concept": "一道柔和的光暈擴散開來，洗淨周圍的污穢並滋養生機。",
  "cast_flavor": "掌心浮起溫潤的光環，隨呼吸緩緩漾開，將周遭的陰翳一一拂去。"
}

{
  "name_zh": "層疊剝離",
  "concept": "以頻率震動撕開敵人的防禦，同時在自身累積額外的能量層數。",
  "cast_flavor": "指尖劃過虛空，殘響如刀般剝落對手的護盾，餘韻沉入骨髓化為新的力量。"
}

{
  "name_zh": "暖流滋養",
  "concept": "將源晶中溫潤的頻率轉化為柔和的能量，滲透並修復單個目標受損的部位。",
  "cast_flavor": "掌心浮起一圈淡金色的光暈，如春水般緩緩流入對方的傷處，驅散內裡的寒意與痛楚。"
}

{
  "name_zh": "暖流滋養",
  "concept": "引導溫和的能量滲透皮膚，修復單個目標受損的部位，驅散內裡的寒意與痛楚。",
  "cast_flavor": "掌心浮起一圈淡金色的光暈，如春水般緩緩流入對方的傷處，撫平撕裂的肌膚與深層的創痛。"
}

{
  "name_zh": "殘光庇佑",
  "concept": "以自身為核心展開的光環，提供護盾並抵消一次致命傷害。",
  "cast_flavor": "周身浮現破碎的晶輝，凝成無形的壁壘抵擋來襲。"
}

{
  "name_zh": "岩層覆體",
  "concept": "大地之力在肌膚表面凝固成堅硬的石質外殼，抵禦傷害。",
  "cast_flavor": "腳下的泥土翻湧而上，纏繞四肢並迅速硬化為粗糙的岩甲。"
}

{
  "name_zh": "高處還生",
  "concept": "從高空垂落的微光觸及亡者，將斷裂的生命重新縫合。",
  "cast_flavor": "一道細長光束自天際墜下，沒入塵土中的軀體，氣息隨之復甦。"
}

{
  "name_zh": "溫潤迴響",
  "concept": "以柔和的頻率在周身形成範圍，持續滋養身後的同伴。",
  "cast_flavor": "低聲吟誦間，一圈溫熱的光暈自腳下漾開，緩慢覆蓋身側。"
}

{
  "name_zh": "柔光環繞",
  "concept": "在周身展開一圈柔和的光暈，持續滋養范围内的同伴。",
  "cast_flavor": "低聲吟誦間，溫熱的光暈自腳下漾開，緩緩覆蓋身側。"
}

{
  "name_zh": "柔光環繞",
  "concept": "在周身展開一圈柔和的光暈，持續滋養範圍內的同伴。",
  "cast_flavor": "低聲吟誦間，溫熱的光暈自腳下漾開，緩緩覆蓋身側。"
}

{
  "name_zh": "燃油衝撞",
  "concept": "以近戰武器直線衝撞，沿途灑落油脂形成滑溜表面。",
  "cast_flavor": "刃尖劃過空氣，拖出一道灼熱的油跡，隨之猛地向前撞去。"
}

{
  "name_zh": "磐石纏身",
  "concept": "大地之力滲透肌膚，形成堅固的岩石層，抵禦外界衝擊。",
  "cast_flavor": "雙足扎根，岩脈沿著皮膚蔓延，將軀體包裹成沉默的堡壘。"
}

