{
  "name_zh": "灼痕點燃",
  "concept": "以純粹的熱能擊中目標，讓其表面迅速升溫並引發持續燃燒。",
  "cast_flavor": "法術凝聚成一點熾烈白光，沒入敵人身軀，皮肉間隨即綻開跳動的火星。"
}

{
  "name_zh": "熾焰灼擊",
  "concept": "凝聚高熱的法術直擊單體目標，造成火焰傷害並使其陷入燃燒狀態。",
  "cast_flavor": "掌心浮起一簇跳動的橘紅火苗，隨指意化為利刃般的光束，狠狠刺入敵人身軀。"
}
